parameters.jsCode:
// Only answers YOUR chat. Everyone else is ignored.
const ALLOWED_CHAT_ID = 'YOUR_CHAT_ID';

const out = [];
for (const item of $input.all()) {
  const u = item.json;
  if (u.callback_query) {
    const cq = u.callback_query;
    const chatId = String(cq.message?.chat?.id ?? cq.from?.id ?? '');
    if (chatId !== ALLOWED_CHAT_ID) continue;
    const [decision, id] = String(cq.data ?? '').split(':');
    if (!['apply', 'skip'].includes(decision) || !/^\d+$/.test(id ?? '')) continue;
    out.push({ json: { kind: 'button', chat_id: chatId, callback_id: cq.id, decision, job_id: Number(id) } });
  } else if (u.message?.text) {
    const chatId = String(u.message.chat.id);
    if (chatId !== ALLOWED_CHAT_ID) continue;
    out.push({ json: { kind: 'text', chat_id: chatId, text: u.message.text } });
  }
}
return out;

// Builds the answer after a button press.
const btn = $('Only allowed chat').first().json;
const row = $input.first()?.json ?? {};
let text;

if (!row.id) {
  text = `ℹ️ Job ${btn.job_id} was already reviewed (or doesn't exist).`;
} else if (row.status === 'approved') {
  text = [
    `✅ Approved: ${row.title} — ${row.company}`,
    ``,
    `👉 Apply here: ${row.url}`,
    ``,
    `📝 Cover letter (copy it if the form asks for one):`,
    ``,
    row.cover_letter ?? '(none)',
    ``,
    `When you've applied, tell me: "mark job ${row.id} as applied".`,
  ].join('\n');
} else {
  text = `❌ Skipped: ${row.title} — ${row.company}`;
}

return [{ json: { chat_id: btn.chat_id, callback_id: btn.callback_id, text: text.slice(0, 4000) } }];

parameters.query:
SELECT s.status, s.jobs, s.avg_score,
       (SELECT count(*) FROM jobs WHERE found_at >= now() - interval '24 hours') AS found_last_24h
FROM pipeline_summary s;
